# Custom CUDA source for squared difference (MSE)
elementwise_mse_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void mse_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float diff = a[idx] - b[idx];
        out[idx] = diff * diff;
    }
}

torch::Tensor mse_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
